function sudanArticle(data) {
  return {
    title:data.title,category:data.category || "Sudan",eyebrow:data.eyebrow,
    infoboxKicker:data.infoboxKicker,infoboxTitle:data.infoboxTitle || data.title,
    lead:data.lead,canon:data.canon,sections:data.sections,related:data.related || sudanRelated,
    sources:data.sources || sudanSources,categories:data.categories || [data.title,"Sudan","Italian Empire"],
    facts:data.facts,landscape:data.landscape,portrait:data.portrait,flag:data.flag
  };
}

Object.assign(window.deepArticles, {
  "sudan":sudanArticle({
    title:"Sudan",eyebrow:"Jointly protected territory · Nile and Red Sea system · 1985",infoboxKicker:"Territorial profile · 1985",infoboxTitle:"Nile Sudan",
    landscape:{src:"assets/sudan-corridor-state.svg",alt:"Diagram of Sudan as a corridor state",caption:"Government is densest along the Nile, railway, Gezira district, Khartoum, and Port Sudan"},
    lead:"Sudan is the jointly protected Nile territory that replaced Anglo–Egyptian rule after the 1947 Lisbon settlement. Italy controls external defense, Port Sudan, Red Sea communications, strategic railways, and the high commission. Egypt supplies much of the administrative language, personnel, finance, and Nile connection. Sudanese officials, police, military units, religious authorities, tribal leaders, land arrangements, and district institutions conduct most government beyond the strategic network.",
    canon:"Transfer from the Anglo–Egyptian system, an Italo–Egyptian condominium or equivalent joint protection, Italian strategic controls, Egyptian administrative participation, local Sudanese government, cotton, livestock, gum arabic, Port Sudan, strategic railways, southern missions, and thinner authority away from corridors are established. The official state name, flag, precise borders, 1985 commissioner, legislative structure, population, ministries, districts, and force totals remain open.",
    sections:[
      {id:"status",title:"Condominium rather than annexation",html:"<p>Sudan is too large, diverse, and administratively thin to become an ordinary Italian colony or an appendage of an Egyptian ministry. Rome and Cairo therefore retain the inherited logic of joint rule while replacing British supremacy with Italian strategic control.</p><p>The title <a href='italo-egyptian-condominium.html'>Italo–Egyptian Condominium</a> describes the system; its exact treaty name remains open.</p>"},
      {id:"history",title:"From Anglo–Egyptian to Italo–Egyptian rule",html:"<p>The 1899 condominium formally joined British and Egyptian authority, though British officials dominated its upper administration. During the long war, remaining British forces in the south lose the material capacity to restore the Nile position.</p><p>The <a href='lisbon-conference.html'>Lisbon settlement</a> transfers Anglo–Egyptian Sudan into the Italian system in 1947. Existing district, tax, railway, military, and agricultural machinery is retained because neither Rome nor Cairo can replace it quickly.</p>"},
      {id:"layers",title:"Three layers of government",html:"<p>The <a href='high-commission-sudan.html'>High Commission</a> holds the strategic reserve. Egyptian officials and finance connect Sudan to the lower Nile and Arabic administrative world. Sudanese district officials, police, soldiers, land authorities, religious leaders, and local intermediaries operate ordinary government.</p><p>The three layers overlap in <a href='khartoum.html'>Khartoum</a>, where strategic decisions must be converted into provincial orders and budgets.</p>"},
      {id:"corridors",title:"A state of points and lines",html:"<p>Control is strongest at Khartoum, <a href='port-sudan.html'>Port Sudan</a>, Atbara, the <a href='gezira-scheme.html'>Gezira irrigation district</a>, the Nile, rail junctions, airfields, garrisons, and principal towns. It grows thinner with distance from the river and railway.</p><p>Peripheral government depends upon negotiated authority, periodic patrols, radio, commodity taxation, and local institutions rather than a dense European bureaucracy.</p>"},
      {id:"economy",title:"Cotton, livestock, gum arabic, and transit",html:"<p>The <a href='sudanese-export-economy.html'>export economy</a> combines irrigated cotton, livestock, gum arabic, port services, railway traffic, and local taxation. Gezira connects Sudanese agriculture to Egyptian finance and Italian textile demand.</p><p>Rome values the territory as much for denial of British return and continuity from Suez to East Africa as for immediate fiscal profit.</p>"},
      {id:"security",title:"Local forces under external command",html:"<p>The <a href='sudan-defence-force.html'>Sudan Defence Force</a>, local police, district units, and tribal or provincial auxiliaries provide routine security. Italian command, aviation, communications, Port Sudan defenses, and mobile reserves control the strategic layer.</p><p>Egyptian officers and institutions remain important, but no Sudanese force receives a complete independent system of external war.</p>"},
      {id:"religion",title:"Islamic north and mission south",html:"<p>Muslim religious leaders, Sufi orders, tribal authorities, courts, and local notables remain indispensable in the north. The <a href='southern-sudan-missions.html'>southern missions</a> retain an outsized role in schooling, medicine, literacy, and local mediation.</p><p>Italian and Vatican patronage favors Christian growth in the south while avoiding a territory-wide religious war. Exact communal law and educational boundaries remain open.</p>"},
      {id:"1985",title:"Sudan in 1985",html:"<p>By 1985 Sudan remains a vast, unequal, and strategically connected protected territory rather than an independent republic. Khartoum governs through institutions whose personnel are increasingly Sudanese, but the external military and financial ceiling remains Italian and Egyptian.</p><p>Its stability rests upon leaving much local authority intact. Its weakness is that the same localism makes central national politics difficult to consolidate.</p>"}
    ],
    related:[{href:"italo-egyptian-condominium.html",kicker:"Constitutional order",label:"Italo–Egyptian Condominium"},{href:"khartoum.html",kicker:"Administrative capital",label:"Khartoum"},{href:"port-sudan.html",kicker:"Red Sea gateway",label:"Port Sudan"},{href:"sudan-railways.html",kicker:"Territorial spine",label:"Sudan Railways"},...sudanRelated],
    facts:[["Capital","Khartoum"],["Status","Italo–Egyptian condominium or equivalent joint protection"],["Strategic authority","Kingdom of Italy"],["Administrative partner","Kingdom of Egypt"],["Local government","Sudanese district institutions and intermediaries"],["Principal port","Port Sudan"],["Principal infrastructure","Nile and Sudan Railways"],["Principal exports","Cotton, livestock, and gum arabic"],["Flag and official title","Open"],["Population","Open"]]
  }),

  "italo-egyptian-condominium":sudanArticle({
    title:"Italo–Egyptian Condominium",eyebrow:"Joint protection · post-Lisbon Sudan",infoboxKicker:"Protectorate constitution",infoboxTitle:"Italo–Egyptian rule in Sudan",
    landscape:{src:"assets/sudan-condominium-authority.svg",alt:"Diagram of authority in jointly protected Sudan",caption:"Italian reserve authority, Egyptian participation, and Sudanese ordinary government"},
    lead:"The Italo–Egyptian Condominium is the system of joint protection governing Sudan after Britain's 1947 withdrawal. It adapts the legal fiction and administrative machinery of the former Anglo–Egyptian Condominium to a new balance: Italy possesses the strategic veto, Egypt supplies the lower-Nile connection and much administrative capacity, and Sudanese authorities operate most district government.",
    canon:"Joint Italian–Egyptian rule or protection and its functional division are established. ‘Italo–Egyptian Condominium’ is the clearest descriptive title but the formal treaty name, founding articles, sovereign formula, flag, commissioner appointment process, legislature, Egyptian share of finance, and amendment history remain open.",
    sections:[
      {id:"inheritance",title:"The 1899 inheritance",html:"<p>The old condominium allowed Britain and Egypt to claim joint authority while British officials controlled the governor-generalship and upper administration. Egyptian officers and finance remained important, and Sudanese officials increasingly staffed the lower system.</p><p>That hierarchy supplies a ready structure when British power collapses.</p>"},
      {id:"transfer",title:"The Lisbon transfer",html:"<p>Britain concedes Sudan with Egypt and the Suez position. Italian forces already face only isolated British remnants incapable of a major counteroffensive.</p><p>Rome accepts the territory to complete a Mediterranean–Red Sea system and deny British return. It does not possess enough administrators to replace the inherited state.</p>"},
      {id:"italy",title:"Italian reserved powers",html:"<p>Italy controls external defense, Port Sudan, Red Sea communications, strategic railways, the high commission, foreign military access, and the principal mobile response system.</p><p>Strategic projects and borrowing require Italian approval even when Egyptian or Sudanese offices execute them.</p>"},
      {id:"egypt",title:"Egyptian participation",html:"<p>Egypt supplies Arabic administrative practice, civil servants, teachers, officers, financial connections, Nile expertise, and commercial access. Cairo treats Sudan as the southern extension of the Nile system rather than an unrelated colony.</p><p>Egypt participates extensively but cannot exclude Italy or convert the condominium into simple Egyptian sovereignty.</p>"},
      {id:"sudanese",title:"Sudanese ordinary government",html:"<p>District officials, police, military units, land and tax arrangements, municipalities, markets, chiefs, religious leaders, and missions supply the state's local reach. Their authority varies by region and is often more continuous than that of the distant high commission.</p><p>The system increasingly relies on Sudanese personnel because European and Egyptian cadres are too few for the territory's scale.</p>"},
      {id:"finance",title:"Finance and commodity taxation",html:"<p>Khartoum and the irrigated districts use money, accounts, and salaried government more regularly. Peripheral authorities may still receive taxes in livestock, grain, gum, or other commodities where lira and Egyptian currency circulate weakly.</p><p>Export boards, railways, port charges, and Egyptian credit convert those local obligations into imperial revenue.</p>"},
      {id:"legitimacy",title:"Legitimacy and the national question",html:"<p>Joint rule prevents annexation by either partner and leaves local institutions intact. It also denies Sudan a single sovereign center from which national independence can develop.</p><p>Educated officials, merchants, officers, religious movements, and regional leaders can therefore disagree over union with Egypt, continued condominium, autonomy, or an independent Sudan. Their parties and leaders remain open.</p>"},
      {id:"maturity",title:"The mature condominium",html:"<p>By 1985 the system is more Sudanese in personnel and more institutional than the emergency transfer of 1947. Its strategic constitution has not liberalized: Italy still commands the Red Sea and external defense, while Egypt remains embedded in administration and finance.</p><p>Visible localization coexists with durable external control.</p>"}
    ],
    related:[{href:"sudan.html",kicker:"Governed territory",label:"Sudan"},{href:"high-commission-sudan.html",kicker:"Strategic office",label:"High Commission for Sudan"},{href:"egypt.html",kicker:"Joint administrator",label:"Kingdom of Egypt"},{href:"lisbon-conference.html",kicker:"Founding settlement",label:"Lisbon Conference"}],
    facts:[["Predecessor","Anglo–Egyptian Condominium"],["Established","After the 1947 Lisbon settlement"],["Strategic partner","Kingdom of Italy"],["Administrative partner","Kingdom of Egypt"],["Local machinery","Sudanese district government"],["Seat","Khartoum"],["Formal treaty title","Open"],["Sovereign and legislative formula","Open"]],
    sources:[...sudanSources,{href:"https://www.loc.gov/item/a22000955/",label:"Library of Congress — historical Anglo–Egyptian Sudan reference"},{href:"https://academic.oup.com/book/62898/chapter-abstract/563974660",label:"Oxford Academic — administration of the Anglo–Egyptian Condominium"}]
  }),

  "high-commission-sudan":sudanArticle({
    title:"High Commission for Sudan",eyebrow:"Italian strategic authority · Khartoum and Port Sudan",infoboxKicker:"Protectorate office",infoboxTitle:"Sudan High Commission",
    landscape:{src:"assets/sudan-condominium-authority.svg",alt:"Diagram of the Sudanese condominium authority",caption:"The high commission controls the strategic reserve rather than every district office"},
    lead:"The High Commission for Sudan is the Italian strategic authority within the postwar condominium. It supervises external defense, Port Sudan, Red Sea communications, strategic railways, foreign access, and the Italian military relationship while Egyptian and Sudanese institutions conduct most finance and ordinary government.",
    canon:"A high commission with Italian control over the listed functions is established. The English title is descriptive; its Italian and Arabic names, founding decree, commissioner list, headquarters, departments, budget, legal relationship to Cairo and Rome, and 1985 officeholder remain open.",
    sections:[
      {id:"purpose",title:"A thin strategic office",html:"<p>The commission is designed for selective control. It cannot administer every market, grazing district, mission school, or village court. It concentrates on the nodes whose possession decides whether another power can use Sudan against Italy.</p><p>Port, rail, radio, airfield, garrison, and budgetary veto matter more than a large civil establishment.</p>"},
      {id:"seat",title:"Khartoum and the Red Sea",html:"<p><a href='khartoum.html'>Khartoum</a> is the natural administrative seat because the Nile branches, railways, finance, military institutions, and district government converge there. <a href='port-sudan.html'>Port Sudan</a> requires a strong subordinate or parallel Italian command.</p><p>The exact distribution between the capital and port remains open.</p>"},
      {id:"defense",title:"External defense",html:"<p>Italian officers direct planning against British return, raids from neighboring territories, or a wider Red Sea crisis. Aviation, communications, heavy weapons, naval liaison, and mobile reserves remain outside purely Sudanese command.</p><p>The local force provides manpower and presence; Italy controls the system capable of sustained external war.</p>"},
      {id:"rail",title:"Railway and communications veto",html:"<p><a href='sudan-railways.html'>Sudan Railways</a>, Nile shipping, radio, telegraph, fuel, and airfields connect distant institutions. Strategic scheduling and protection therefore fall within the commission's reserve.</p><p>Commercial and passenger operation may remain Sudanese while mobilization and foreign access require Italian approval.</p>"},
      {id:"egypt",title:"Relationship with Egyptian ministries",html:"<p>Egyptian officials, banks, officers, teachers, and engineers are partners rather than simple subordinates. The commission must bargain with Cairo because Egyptian administrative participation makes the condominium governable.</p><p>Rome retains the final strategic veto, especially where Nile development, borrowing, or military policy affects Suez and East Africa.</p>"},
      {id:"districts",title:"Indirect district government",html:"<p>The commission works through Sudanese provincial officials, local police, religious authorities, land arrangements, chiefs, merchants, and missions. A decision made in Khartoum may be negotiated again before it becomes effective in a peripheral district.</p><p>This is an accepted feature of corridor rule rather than proof that the state has no reach.</p>"},
      {id:"politics",title:"An office of patronage and surveillance",html:"<p>Appointments, railway contracts, export licenses, mission permissions, military commissions, and development funds create political clients. Intelligence monitors officers, educated officials, religious movements, labor, and foreign contacts.</p><p>Exact security departments and emergency powers remain unregistered.</p>"}
    ],
    related:[{href:"italo-egyptian-condominium.html",kicker:"Constitutional system",label:"Italo–Egyptian Condominium"},{href:"port-sudan.html",kicker:"Principal strategic node",label:"Port Sudan"},{href:"sudan-defence-force.html",kicker:"Local military instrument",label:"Sudan Defence Force"},{href:"sudan-railways.html",kicker:"Communications reserve",label:"Sudan Railways"}],
    facts:[["Seat","Khartoum; exact premises open"],["Principal strategic station","Port Sudan"],["Controlling power","Kingdom of Italy"],["Partner","Kingdom of Egypt"],["Reserved fields","External defense, Red Sea, railways, foreign access"],["Local executors","Sudanese officials and forces"],["Formal title and commissioner list","Open"]]
  }),

  "khartoum":sudanArticle({
    title:"Khartoum",eyebrow:"Capital of jointly protected Sudan · Nile confluence",infoboxKicker:"Capital city",infoboxTitle:"Khartoum",
    landscape:{src:"assets/sudan-corridor-state.svg",alt:"Diagram of Khartoum within the Sudanese corridor system",caption:"Khartoum joins the Nile, railway, administration, finance, and security networks"},
    lead:"Khartoum is the capital and principal administrative junction of jointly protected Sudan. At the confluence of the Blue and White Nile, it connects the high commission, Sudanese departments, Egyptian personnel and finance, the railway system, military institutions, export administration, and the neighboring urban centers of Omdurman and Khartoum North.",
    canon:"Khartoum's capital role, Nile and railway importance, condominium administration, and connection to Egyptian and Italian authority are established by geography and the setting's governing structure. Population, municipal boundaries, commissioner residence, ministries, urban planning, transport, and detailed postwar political history remain open.",
    sections:[
      {id:"confluence",title:"Capital at the confluence",html:"<p>The meeting of the Blue and White Nile gives Khartoum command of river movement between Egypt, Gezira, the south, and the Ethiopian approaches. Railway links add an eastward line through Atbara to Port Sudan.</p><p>The capital's importance is therefore logistical before it is ceremonial.</p>"},
      {id:"three-cities",title:"The three-city metropolis",html:"<p>Khartoum, Omdurman, and Khartoum North form a connected urban system with distinct administrative, commercial, military, religious, and residential histories. Bridges and ferries turn the confluence into an urban geography as well as a barrier.</p><p>Exact municipal consolidation and planning after 1947 remain open.</p>"},
      {id:"government",title:"Capital of divided authority",html:"<p>The <a href='high-commission-sudan.html'>High Commission</a>, Sudanese departments, Egyptian liaison offices, military headquarters, courts, banks, and export boards coexist in the capital.</p><p>Sudanese officials increasingly conduct daily administration, while strategic files involving defense, Port Sudan, railways, foreign access, or major finance move through Italian and Egyptian review.</p>"},
      {id:"economy",title:"Finance, trade, and transport",html:"<p>Khartoum organizes railway schedules, Nile transport, public accounts, agricultural credit, military supply, professional services, and wholesale trade. It is less an export port than the place where inland production becomes legible to the state.</p><p>The city links Gezira cotton and peripheral commodities to Port Sudan and Egyptian markets.</p>"},
      {id:"society",title:"Officials, officers, merchants, and students",html:"<p>Government employment, military service, teaching, medicine, law, transport, and commerce create an educated urban public. Sudanese professionals work beside Egyptian and Italian officials without possessing equal access to the strategic state.</p><p>That contradiction makes the capital the likely center of nationalist and constitutional argument, though named parties and leaders remain open.</p>"},
      {id:"religion",title:"Islamic and mission institutions",html:"<p>Omdurman and Khartoum contain important Muslim religious, scholarly, and political networks. Christian churches, schools, hospitals, and missions serve communities connected to the south, Egypt, Ethiopia, and the wider imperial system.</p><p>Italian policy favors Christian institutions selectively while depending upon Muslim authorities for most northern governance.</p>"},
      {id:"security",title:"A guarded administrative hub",html:"<p>The capital contains barracks, communications, depots, police, and the command functions required to move forces along the Nile and railway. Italian personnel concentrate in command, aviation, communications, and strategic liaison rather than every neighborhood patrol.</p><p>The exact garrison and emergency plan remain open.</p>"}
    ],
    related:[{href:"sudan.html",kicker:"Capital territory",label:"Sudan"},{href:"italo-egyptian-condominium.html",kicker:"Government system",label:"Italo–Egyptian Condominium"},{href:"sudan-railways.html",kicker:"Land connection",label:"Sudan Railways"},{href:"gezira-scheme.html",kicker:"Agricultural hinterland",label:"Gezira Scheme"},{href:"capitals-of-latin-system.html",kicker:"Regional comparison",label:"Capital Cities of the Latin System"}],
    facts:[["Territory","Sudan"],["Role","Capital and administrative junction"],["Geography","Blue and White Nile confluence"],["Urban system","Khartoum, Omdurman, Khartoum North"],["Principal institutions","High Commission and Sudanese departments"],["Transport","Nile and railway junction"],["Population and municipal structure","Open"]]
  }),

  "port-sudan":sudanArticle({
    title:"Port Sudan",eyebrow:"Red Sea port · Italian strategic reserve",infoboxKicker:"Strategic port city",infoboxTitle:"Port Sudan",
    landscape:{src:"assets/sudan-corridor-state.svg",alt:"Diagram of Port Sudan and the Khartoum railway",caption:"The Red Sea gateway sits at the end of Sudan's most closely controlled eastward corridor"},
    lead:"Port Sudan is the principal Red Sea port of the condominium and the Sudanese site most directly controlled by Italy. Rail traffic from Khartoum and the interior terminates at its docks, where cotton, gum arabic, livestock products, imports, fuel, military supply, and imperial shipping enter the Mediterranean–Red Sea system.",
    canon:"Italian control of Port Sudan, Red Sea communications, strategic railways, and external defense is established. The port's inherited commercial role is historical. Exact harbor capacity, naval command, fortifications, municipal government, population, ethnic communities, reconstruction, and 1985 garrison remain open.",
    sections:[
      {id:"foundation",title:"A railway port on the Red Sea",html:"<p>Built in the early twentieth century as the modern outlet of Anglo–Egyptian Sudan, Port Sudan was linked to Khartoum by rail in 1906. Its growth redirected much long-distance commerce from older Suakin.</p><p>Italy inherits a functioning harbor and transport corridor rather than creating a port from empty coast.</p>"},
      {id:"transfer",title:"Transfer into the Italian system",html:"<p>Lisbon places the port inside the new condominium while reserving its strategic operation to Italy. The harbor completes Rome's route from Suez along the western Red Sea toward Eritrea, Ethiopia, Somalia, and the Indian Ocean.</p><p>Control denies Britain an easy return to the Sudanese interior.</p>"},
      {id:"commerce",title:"Exports, imports, and port services",html:"<p>Cotton, gum arabic, hides, livestock products, and other commodities move east by rail. Machinery, textiles, fuel, vehicles, manufactured goods, and military stores move inland.</p><p>Dock labor, warehousing, customs, shipping agencies, repair, insurance, and rail transfer make port services a major source of revenue.</p>"},
      {id:"authority",title:"Direct strategic supervision",html:"<p>Sudanese municipal and commercial offices conduct ordinary work, but naval access, external security, fuel, communications, military cargo, foreign warships, and strategic scheduling fall under the <a href='high-commission-sudan.html'>High Commission</a> and Italian command.</p><p>The division is more visibly imperial here than in most inland districts.</p><!-- altwwii-writer-block:start id=wb-v-20260816-295ac writer=v kind=extrapolation created=2026-08-16T11:57:44-06:00 --><p>Sudanese port and railway offices prepared ordinary berth and train schedules. An Italian reservation of a berth, fuel stock, rail slot, or communications circuit for protected traffic forced those offices to rework labor, warehouse, customs, and commercial movements around it. Strategic control could operate as a veto or insertion in a locally run schedule, with delay recorded against displaced civilian cargo.</p><!-- altwwii-writer-block:end -->"},
      {id:"rail",title:"The Port Sudan–Atbara–Khartoum line",html:"<p>The railway binds harbor capacity to the capital and Nile economy. Atbara's workshops and junction functions make the route a chain of institutions rather than a single track.</p><p>Italian planners protect bridges, workshops, telegraph, fuel, and rolling stock because the port is only as useful as its inland connection.</p>"},
      {id:"red-sea",title:"Red Sea defense and communications",html:"<p>Port Sudan supports patrol, convoy, air, radio, weather, rescue, inspection, and logistics functions. It connects northward to <a href='suez-canal-zone.html'>Suez</a> and southward to <a href='massawa.html'>Massawa</a>, Assab, and the <a href='italian-east-africa.html'>East African system</a>.</p><p>Exact naval formations and base boundaries remain open.</p>"},
      {id:"city",title:"A Sudanese city inside an imperial port",html:"<p>Merchants, dock workers, railwaymen, sailors, pastoral traders, officials, soldiers, and foreign commercial communities give the city a social life broader than the base.</p><p>Its political question mirrors Sudan's: whether locally staffed institutions can acquire sovereignty while the strategic infrastructure remains external.</p><!-- altwwii-writer-block:start id=wb-i-20260816-h4t8c writer=i kind=analysis created=2026-08-16T12:25:13-06:00 --><p>Port records make berth reservations, fuel, cargo priorities, rail movements, and delays unusually visible. They show where Italian command could interrupt Sudanese work; they do not provide a census of urban authority. Customs clerks, warehouse staff, railway workers, dock laborers, merchants, sailors, repair workers, and pastoral traders continued to turn schedules into loading, storage, provisioning, wages, and inland exchange.</p><p>Strategic insertion redistributed time and uncertainty. A displaced civilian wagon or berth could appear as an accounting entry to the High Commission, while workers, merchants, and producers experienced shifts, storage, stocks, payment, or market access rearranged by a priority set elsewhere. Compliance kept cargo moving. It did not make port labor or municipal life Italian, and it did not demonstrate consent to condominium rule.</p><!-- altwwii-writer-block:end -->"}
    ],
    related:[{href:"sudan-railways.html",kicker:"Inland connection",label:"Sudan Railways"},{href:"high-commission-sudan.html",kicker:"Strategic authority",label:"High Commission for Sudan"},{href:"sudanese-export-economy.html",kicker:"Commercial hinterland",label:"Sudanese Export Economy"},{href:"suez-canal-zone.html",kicker:"Northern route",label:"Suez Canal Zone"}],
    facts:[["Territory","Sudan"],["Sea","Red Sea"],["Rail connection to Khartoum","1906 historical baseline"],["Primary role","Export port and strategic base"],["Strategic controller","Kingdom of Italy"],["Commercial administration","Sudanese and condominium institutions"],["Capacity and garrison","Open"]],
    sources:[...sudanSources,{href:"https://sudanrailways.gov.sd/History",label:"Sudan Railways — historical Khartoum–Port Sudan connection"}]
  }),

  "sudan-railways":sudanArticle({
    title:"Sudan Railways",eyebrow:"State railway · strategic communications system",infoboxKicker:"Transport institution",infoboxTitle:"Sudan Railways",
    landscape:{src:"assets/sudan-corridor-state.svg",alt:"Diagram of the Sudan railway and Nile corridor",caption:"Rail links the capital, irrigation districts, workshops, export regions, and Red Sea port"},
    lead:"Sudan Railways is the territorial spine of the condominium state. Its principal network links Khartoum and the Nile system through Atbara to Port Sudan, with branches serving irrigated cotton, western commodities, provincial centers, and military districts. Commercial operation is Sudanese; strategic scheduling, protection, and foreign military access remain subject to Italian control.",
    canon:"Strategic railways under Italian control and their importance to corridor government are established. The inherited Sudan network is historical. Post-1947 extensions, gauge changes, locomotives, corporate charter, employment totals, electrification, finances, timetables, and 1985 route map remain open.",
    sections:[
      {id:"inheritance",title:"The inherited network",html:"<p>Railways built during the conquest and condominium eras connected the Nile, military administration, agricultural districts, and the new Red Sea port. Khartoum reached Port Sudan in 1906, with Atbara developing as a junction and workshop center.</p><p>The line already embodied the old state's geography before Italy arrived.</p>"},
      {id:"spine",title:"Khartoum, Atbara, and Port Sudan",html:"<p>The capital provides administration and Nile interchange, Atbara provides workshops and route division, and Port Sudan provides maritime access. Failure at any one node interrupts the whole eastern corridor.</p><p>Italian strategic attention therefore concentrates on the connected system rather than the port alone.</p>"},
      {id:"interruption",title:"Traffic during an interruption",html:"<!-- altwwii-writer-block:start id=wb-v-20260816-h6r3n writer=v kind=extrapolation created=2026-08-16T13:56:00-06:00 --><p>A station receiving notice of blocked track, bridge trouble, flood damage, failed signaling, or an immobilized train held following traffic at a place with water, communication, siding space, and some provision for passengers or freight. Telegraph and station reports identified the affected section, trains already inside it, loads requiring attention, and the nearest crews or equipment able to inspect the line. Atbara's workshops and route position made it a natural source of repair assistance without making every incident subject to one central office.</p><p>Dispatchers could turn a train back, stage it in a yard, detach urgent wagons, or transfer a limited load to Nile craft or road vehicles where those alternatives existed. Their capacity was too small to replace the railway corridor. After reopening, accumulated trains competed for locomotives, crews, wagons, paths, and unloading space; passenger need, spoilage, livestock care, government direction, and Italian strategic priority could alter the order. Freight and station records carried the delay and change of custody forward when goods no longer arrived on the planned train.</p><!-- altwwii-writer-block:end -->"},
      {id:"agriculture",title:"Agricultural branches",html:"<p>Rail serves <a href='gezira-scheme.html'>Gezira cotton</a>, gum-producing regions, livestock markets, grain districts, and storage centers. It transforms bulky or distant commodities into taxable exports.</p><p>Branch construction follows economic and security priorities; exact postwar routes remain open.</p>"},
      {id:"government",title:"Railway as government",html:"<p>Stations, workshops, telegraph, payrolls, police, freight offices, medical services, and housing make the railway one of the few continuous institutions across the territory.</p><p>Where roads and district bureaucracy are thin, a station may be the most regular face of central government.</p>"},
      {id:"authority",title:"Commercial management and strategic veto",html:"<p>Sudanese railway personnel operate trains, workshops, accounts, and freight services. Egyptian engineers and finance remain influential. Italian authority controls mobilization, military priority, external access, and protection of key infrastructure.</p><p>This division mirrors the condominium constitution.</p>"},
      {id:"labor",title:"Railway labor and politics",html:"<p>Skilled workers, clerks, drivers, engineers, telegraphers, and workshop communities form an organized urban workforce. Their ability to halt movement gives labor disputes potential political weight beyond their numbers.</p><p>Named unions, strikes, and political affiliations after 1947 remain open.</p>"},
      {id:"limits",title:"Limits of the steel corridor",html:"<p>Railways concentrate government along fixed lines while leaving large areas distant from regular transport. Seasonal conditions, maintenance, imported equipment, and workshop capacity constrain expansion.</p><p>The network makes Sudan governable as a corridor state; it does not make the territory uniformly administered.</p>"}
    ],
    related:[{href:"port-sudan.html",kicker:"Maritime terminus",label:"Port Sudan"},{href:"khartoum.html",kicker:"Administrative junction",label:"Khartoum"},{href:"gezira-scheme.html",kicker:"Agricultural traffic",label:"Gezira Scheme"},{href:"high-commission-sudan.html",kicker:"Strategic supervision",label:"High Commission for Sudan"}],
    facts:[["Type","Government railway system"],["Principal axis","Khartoum–Atbara–Port Sudan"],["Historical Red Sea connection","1906"],["Commercial operator","Sudanese railway administration"],["Strategic authority","Italian High Commission"],["Principal freight","Cotton, gum arabic, livestock products, imports"],["1985 route length and equipment","Open"]],
    sources:[...sudanSources,{href:"https://sudanrailways.gov.sd/History",label:"Sudan Railways — official historical chronology"},{href:"https://sudanrailways.gov.sd/About",label:"Sudan Railways — network and traffic overview"}]
  }),

  "gezira-scheme":sudanArticle({
    title:"Gezira Scheme",eyebrow:"Irrigation district · cotton and Nile development",infoboxKicker:"Agricultural system",infoboxTitle:"Gezira irrigation scheme",
    landscape:{src:"assets/sudan-corridor-state.svg",alt:"Diagram of the Gezira district in the Sudanese corridor",caption:"Gezira turns Blue Nile water, land, labor, rail, and credit into the condominium's principal cotton system"},
    lead:"The Gezira Scheme is the large irrigated agricultural system between the Blue and White Nile south of Khartoum. Built around gravity irrigation and cotton, it becomes the most administratively dense rural district of jointly protected Sudan and the principal material connection among Sudanese cultivators, Egyptian Nile expertise, Italian textile demand, railway transport, and condominium finance.",
    canon:"Cotton as a principal Italian interest and Nile communication are established; Gezira's inherited centrality is historical and a necessary continuation. Post-1947 management, acreage, tenant contracts, crop rotation, extension dates, output, prices, and exact Italian or Egyptian board participation remain open.",
    sections:[
      {id:"origins",title:"Origins of the scheme",html:"<p>The Sennar Dam and gravity canals made large-scale cotton cultivation possible from the 1920s. A central board coordinated water, land, tenants, ginning, finance, transport, and export.</p><p>By 1947 the system is too important and technically integrated to dismantle during the transfer of power.</p>"},
      {id:"water",title:"Nile water and engineering",html:"<p>Dams, canals, regulators, drainage, survey, maintenance, and planting schedules turn river flow into predictable production. Egyptian engineers and officials possess obvious expertise and political interest in the Nile system.</p><p>Italian strategic supervision ensures that major works and external borrowing fit the wider imperial plan.</p>"},
      {id:"cotton",title:"Cotton and imperial demand",html:"<p>Cotton supplies export earnings, railway freight, port traffic, ginning, and Italian textile procurement. It links Sudan to the <a href='egyptian-cotton-economy.html'>larger Nile cotton economy</a> without making the two systems identical.</p><p>Dependence on one principal export leaves cultivators and the state exposed to prices, water, pests, and maintenance failures.</p>"},
      {id:"cultivators",title:"Cultivators, land, and administration",html:"<p>Sudanese cultivators work inside a managed relationship among land rights, water allocation, crop rules, credit, and compulsory services. District officials and local authorities mediate between the board and rural communities.</p><p>The exact postwar tenant settlement remains open and should not be reduced to invented percentages.</p><!-- altwwii-writer-block:start id=wb-i-20260816-j5m9d writer=i kind=analysis created=2026-08-16T12:27:33-06:00 --><p>Board records separated water allotments, land registration, crop orders, credit, service obligations, and deliveries into administrative categories. A cultivator household met them together. Water and crop rules organized its agricultural season, credit placed claims on later income, compulsory services claimed labor, and registered land rights determined continued access to the scheme.</p><p>Production accounts made acreage, yield, deliveries, and arrears visible more readily than subsistence, unpaid family work, care, maintenance, or risk. Local authorities supplied knowledge of households, fields, water, and labor that the central board could not reproduce. That position allowed mediation, patronage, and coercion to coexist. Continued cultivation could express dependence upon land, water, and credit as readily as approval of condominium government.</p><!-- altwwii-writer-block:end -->"},
      {id:"transport",title:"Ginneries, railways, and Port Sudan",html:"<p>Seed cotton moves to ginneries and then by <a href='sudan-railways.html'>rail</a> toward <a href='port-sudan.html'>Port Sudan</a>. Machinery, fertilizer, fuel, tools, and consumer goods move back through the same corridor.</p><p>The scheme is therefore an industrial-transport system as well as an irrigation project.</p>"},
      {id:"politics",title:"Development and dependency",html:"<p>Khartoum can present Gezira as evidence that joint rule produces modern infrastructure and regular income. Sudanese critics can point to foreign control of credit, export markets, water strategy, and the highest decisions.</p><p>Technical development creates an educated managerial class capable of demanding greater national authority.</p>"},
      {id:"1985",title:"Gezira in the mature condominium",html:"<p>By 1985 the scheme remains a core revenue and administrative district even as livestock, gum arabic, port services, and other crops diversify the economy.</p><p>Its precise later expansion and performance remain open, but no credible Sudanese state can ignore the institutions built around its water and cotton.</p>"}
    ],
    related:[{href:"sudanese-export-economy.html",kicker:"Wider economy",label:"Sudanese Export Economy"},{href:"sudan-railways.html",kicker:"Export route",label:"Sudan Railways"},{href:"khartoum.html",kicker:"Administrative center",label:"Khartoum"},{href:"egyptian-cotton-economy.html",kicker:"Northern comparison",label:"Egyptian Cotton Economy"}],
    facts:[["Region","Between the Blue and White Nile"],["Origin","Large-scale scheme from 1925"],["Water source","Blue Nile through the Sennar system"],["Principal crop","Cotton"],["Transport outlet","Sudan Railways to Port Sudan"],["Administrative form","Board and district system; later details open"],["1985 acreage and output","Open"]],
    sources:[...sudanSources,{href:"https://documents.worldbank.org/en/publication/documents-reports/documentdetail/539061468304195366",label:"World Bank — history and political economy of the Gezira Scheme"}]
  }),

  "sudan-defence-force":sudanArticle({
    title:"Sudan Defence Force",eyebrow:"Local armed force · condominium security",infoboxKicker:"Military institution",infoboxTitle:"Sudan Defence Force",
    lead:"The Sudan Defence Force is the local military institution inherited by the postwar condominium. Formed in 1925 under Anglo–Egyptian rule, it survives the 1947 transfer because the new authorities need Sudanese formations for garrison, frontier, railway, district, and internal-security duties. Italian command controls external defense and the strategic systems beyond the force's independent reach.",
    canon:"Local Sudanese military units, Egyptian and Sudanese formations, and Italian control of external defense are established. Continuation of the historical Sudan Defence Force is a strong institutional inference. Its later official name, battalions, recruitment regions, commanders, uniforms, weapons, aviation, police relationship, and 1985 strength remain open.",
    sections:[
      {id:"formation",title:"Formation under the old condominium",html:"<p>The Sudan Defence Force was established in 1925 from existing Sudanese military units to provide local defense and internal security under the governor-general's command. Recruitment and organization reflected regional, ethnic, and administrative divisions.</p><p>Its personnel and barracks make it one of the few national-scale institutions available in 1947.</p>"},
      {id:"transfer",title:"Transfer after Lisbon",html:"<p>British officers depart or are repatriated while Sudanese soldiers, noncommissioned officers, installations, and much routine administration remain. Egyptian and Italian officers enter supervisory and liaison roles.</p><p>The exact sequence of oaths, retirement, reorganization, and renaming remains open.</p>"},
      {id:"roles",title:"Garrison, railway, and district roles",html:"<p>Registered functions support frontier posts, railway and bridge security, port approaches, district reinforcement, communications, patrol, and support to local police. Mobile units extend the state's reach beyond permanent garrisons.</p><p>The force is designed for presence and containment rather than independent theater war.</p>"},
      {id:"command",title:"National personnel, external command",html:"<p>Sudanese officers and soldiers can command units and conduct ordinary operations. Italian authority retains aviation, heavy communications, strategic logistics, Port Sudan defense, foreign liaison, and mobilization priorities.</p><p>Egyptian military institutions supply training and personnel connections without displacing the Italian veto.</p>"},
      {id:"recruitment",title:"Regional recruitment and political balance",html:"<p>Recruitment by region and community can provide local expertise while allowing the state to deploy units away from their home districts. It can also reproduce the divisions through which the condominium governs.</p><p>Exact corps identities and recruitment rules after 1947 remain open.</p>"},
      {id:"politics",title:"Officers and the sovereignty question",html:"<p>A Sudanese officer corps embodies national capacity while serving a state that lacks independent external command. Promotion, training, deployment, and access to strategic weapons therefore carry political meaning.</p><p>Named conspiracies, mutinies, and nationalist networks have not been established and should not be invented.</p>"},
      {id:"1985",title:"Force in 1985",html:"<p>By 1985 the local force is more Sudanese in leadership and routine operation than at the transfer. It remains integrated into an Italian-controlled Red Sea and Nile defense system.</p><p>Its exact name may have changed, but its constitutional function endures: national manpower beneath condominium strategy.</p>"}
    ],
    related:[{href:"high-commission-sudan.html",kicker:"Strategic command",label:"High Commission for Sudan"},{href:"sudan.html",kicker:"Territorial context",label:"Sudan"},{href:"sudan-railways.html",kicker:"Protected infrastructure",label:"Sudan Railways"},{href:"port-sudan.html",kicker:"External-defense node",label:"Port Sudan"}],
    facts:[["Founded","1925 historical baseline"],["Predecessor system","Anglo–Egyptian Condominium"],["Postwar allegiance","Sudanese condominium authorities"],["Strategic command","Italian-controlled"],["Roles","Garrison, frontier, railway, district security"],["Egyptian role","Training and institutional liaison"],["Later name and force totals","Open"]],
    sources:[...sudanSources,{href:"https://en.wikipedia.org/wiki/Sudan_Defence_Force",label:"Sudan Defence Force — historical institutional baseline"}]
  }),

  "southern-sudan-missions":sudanArticle({
    title:"Southern Sudan Missions",eyebrow:"Religion, education, and district government",infoboxKicker:"Religious institutions",infoboxTitle:"Christian missions in southern Sudan",
    lead:"The southern Sudan missions are the Catholic, Protestant, and local Christian institutions that provide schools, clinics, literacy, clergy, translation, charity, and mediation in districts where condominium government is thin. Italian and Vatican patronage strengthens Catholic institutions after 1947, but existing missions and emerging local churches remain too useful and rooted to be replaced wholesale.",
    canon:"Continuing missions in the south, a later strong Christian south, Italian support for Christian institutions, and indirect district government are established. Mission societies, dioceses, languages, school numbers, denominational boundaries, conversion rates, clergy, southern administrative borders, and relations with local religions remain open.",
    sections:[
      {id:"inheritance",title:"The mission inheritance",html:"<p>Under the old condominium, missions became important providers of education, medicine, literacy, translation, and local contact in southern districts. Administrative separation from the Arabic-speaking north gave religious institutions an additional political role.</p><p>The 1947 transfer changes their patrons but does not remove the need they serve.</p>"},
      {id:"italian",title:"Italian and Vatican policy",html:"<p>Italy favors Christian institutional growth, especially Catholic schools, hospitals, orders, and clergy. The Vatican supports evangelization while resisting forced conversion, racial sacramental distinctions, state ownership of missions, and compulsory Latinization.</p><p>The protectorate wants loyal institutions; the Church wants durable Christian communities.</p>"},
      {id:"authority",title:"Mission authority and public service",html:"<!-- altwwii-writer-block:start id=wb-c-20260816-7f96d writer=c kind=analysis created=2026-08-16T12:21:59-06:00 --><p>The term <em>Catholic mission</em> covered several authorities. A religious superior governed members and the internal life of an institute. A diocesan or missionary ordinary governed the local ecclesiastical work entrusted to him. A school or hospital superior administered a particular institution under its statutes. Italian, Egyptian, and Sudanese authorities issued civil licenses, grants, land arrangements, transport access, curricula, and health rules within their competence. None of those acts alone made a mission society a diocese or a civil official an ecclesiastical superior.</p><p>State funds and protection could make mission schools and clinics part of the region's public provision without turning them into state departments. Civil authorities could enforce genuine educational, medical, labor, and safety standards. They could not appoint clergy, direct sacraments, or make baptism, worship, or Catholic instruction a condition of treatment, relief, ordinary schooling, employment, or legal protection. Protestant and local Christian bodies retained their own government; their tolerated or subsidized work did not amount to Catholic approval of doctrine.</p><p>The documentary record must therefore identify the institution, superior, grant, recipient, and condition. Teachers, nurses, catechists, translators, women religious, local clergy, and lay families often performed the continuing work described generically as missionary activity. Their registers can preserve language, kinship, health, and conversion histories absent from district files. The same records and local knowledge could also assist taxation, recruitment, movement control, or surveillance, so institutional survival and public service do not by themselves establish either free consent or political independence.</p><!-- altwwii-writer-block:end -->"},
      {id:"plural",title:"Catholic privilege and Christian plurality",html:"<p>Catholic organizations gain money, permissions, personnel, and connections to the Latin system. Older Protestant missions, local congregations, and independent Christian networks may continue where abrupt suppression would destroy schools and medicine or provoke foreign controversy.</p><p>The exact denominational settlement remains open.</p>"},
      {id:"education",title:"Schools, medicine, and literacy",html:"<p>Mission schools train teachers, clerks, nurses, catechists, translators, and local officials. Clinics and hospitals supply services that the thin district state cannot reproduce everywhere.</p><p>Education gives southern Christians greater access to salaried administration while also producing leaders capable of challenging northern and foreign authority.</p>"},
      {id:"government",title:"Missions as local intermediaries",html:"<p>District officers use missions for information, communication, relief, mediation, and the administration of remote communities. Missionaries depend on police protection, licenses, transport, and grants.</p><p>The relationship is reciprocal and unequal rather than a simple fusion of church and state.</p>"},
      {id:"identity",title:"Southern identity and the condominium",html:"<p>Christian institutions, local languages, and distance from Khartoum strengthen a southern political identity distinct from the Muslim and Arabic-speaking north. The condominium's reliance on regional difference can preserve communities while making a common Sudanese national project harder.</p><p>No fixed secession movement or civil war chronology has been registered.</p>"},
      {id:"1985",title:"A strong Christian south",html:"<p>By 1985 southern Sudan contains durable Christian institutions rather than a temporary mission frontier. Growth results from education, medicine, protected conversion, local clergy, family networks, and decades of unequal patronage.</p><p>Exact demographic proportions and the balance among Catholic, Protestant, and indigenous Christian bodies remain open.</p>"}
    ],
    related:[{href:"sudan.html",kicker:"Territorial setting",label:"Sudan"},{href:"italo-egyptian-condominium.html",kicker:"Political order",label:"Italo–Egyptian Condominium"},{href:"catholic-church.html",kicker:"Wider ecclesiastical system",label:"Catholic Church"},{href:"coptic-orthodox-church-egypt.html",kicker:"Northern Christian comparison",label:"Coptic Orthodox Church in Egypt"}],
    facts:[["Region","Southern Sudan"],["Functions","Schools, clinics, literacy, translation, charity"],["Post-1947 patronage","Italian state and Catholic networks"],["Other institutions","Protestant and local Christian bodies"],["Government role","District intermediaries"],["1985 outcome","Strong Christian institutional field"],["Demography and denominations","Open"]]
  }),

  "sudanese-export-economy":sudanArticle({
    title:"Sudanese Export Economy",eyebrow:"Cotton · livestock · gum arabic · transit",infoboxKicker:"Economic system",infoboxTitle:"Export economy of Sudan",
    landscape:{src:"assets/sudan-corridor-state.svg",alt:"Diagram of Sudanese production and transport corridors",caption:"Exports become imperial revenue where local production meets rail, river, Khartoum, and Port Sudan"},
    lead:"The Sudanese export economy links irrigated cotton, livestock, gum arabic, hides, local crops, railway traffic, and Port Sudan services to Egyptian finance and Italian markets. Its productive districts support the condominium, but its geography reinforces corridor rule: commodities become legible and taxable chiefly when they reach a market, river landing, railway station, export board, or port.",
    canon:"Cotton, livestock, gum arabic, Nile communication, Port Sudan, strategic railways, local tax arrangements, and commodity collection where money is scarce are established. Output, prices, firms, concessions, currency shares, land tenure, labor law, processing capacity, trade partners, and 1985 national accounts remain open.",
    sections:[
      {id:"structure",title:"An economy of several Sudans",html:"<p>The irrigated Nile districts, rain-fed farming regions, pastoral zones, gum-producing woodlands, towns, railway settlements, and Red Sea port do not operate through one uniform market.</p><p>The state joins them through transport, licenses, commodity boards, taxes, credit, and strategic purchasing.</p>"},
      {id:"cotton",title:"Cotton and Gezira",html:"<p>The <a href='gezira-scheme.html'>Gezira Scheme</a> supplies the most organized cotton system, with irrigation, board management, ginning, rail, finance, and export contracts. Smaller cotton districts add to the trade.</p><p>Italian textile demand and Egyptian expertise make the crop central to joint administration.</p>"},
      {id:"livestock",title:"Livestock and pastoral exchange",html:"<p>Cattle, sheep, goats, hides, transport animals, and related trade connect pastoral regions to towns and export routes. Local leaders and merchants often matter more than distant ministries in organizing movement.</p><p>Veterinary services, water, quarantine, rail, and market access become tools of government.</p><!-- altwwii-writer-block:start id=wb-i-20260816-k6p2f writer=i kind=analysis created=2026-08-16T12:28:59-06:00 --><p>Administrative records encountered herds at water points, veterinary stations, quarantine lines, markets, railheads, and tax collection. Pastoral households encountered those sites while deciding movement, animal health, sale, transport, and access to cash or goods. The condominium could govern a route selectively at such nodes without maintaining continuous officials across the grazing country between them.</p><p>Officials depended on leaders and merchants who knew seasonal routes, herd locations, household claims, and local exchange. That knowledge made veterinary work and commodity collection possible and also converted brokerage into a source of patronage or coercion. Water and animal care had real value, while quarantine, licenses, wagon allocation, and taxation could narrow the available choices. Use of a service or market did not demonstrate acceptance of external rule.</p><!-- altwwii-writer-block:end -->"},
      {id:"gum",title:"Gum arabic",html:"<p>Gum arabic is valuable because it can be gathered across regions where intensive central administration is weak, then concentrated through merchants and transport nodes for export.</p><p>Licensing, grading, purchasing, and railway access allow the condominium to tax the trade without governing every producing community directly.</p>"},
      {id:"currency",title:"Money and commodity taxation",html:"<p>Lira, Egyptian-linked money, local credit, barter, and commodity obligations coexist unevenly. In districts with little cash, officials may accept grain, livestock, gum, or other goods and convert them through merchants or public purchasing.</p><p>Expanding paid employment and imperial purchasing gradually creates a broader taxable monetary economy.</p>"},
      {id:"transport",title:"Rail, river, and port",html:"<p>Nile transport and <a href='sudan-railways.html'>Sudan Railways</a> carry commodities toward Khartoum and <a href='port-sudan.html'>Port Sudan</a>. Freight rates, wagon allocation, storage, and port scheduling determine which regions can profitably enter export markets.</p><p>Transport policy is therefore also regional policy.</p>"},
      {id:"distribution",title:"Who receives the value",html:"<p>Cultivators, pastoralists, local merchants, chiefs, export houses, railways, port firms, banks, Egyptian administrators, and Italian concession interests divide the proceeds unequally.</p><p>Exact shares remain open, but the political dispute is clear: Sudan produces strategic value while foreign institutions control much of its external route and finance.</p>"},
      {id:"1985",title:"The mature export corridor",html:"<p>By 1985 the economy is more monetized and institutionally connected than in 1947, yet it remains uneven. Productive corridors can support regular government while distant districts depend on negotiated authority and irregular market access.</p><p>The export system sustains the condominium and gives Sudanese officials and merchants the capacity to imagine a more autonomous one.</p>"}
    ],
    related:[{href:"gezira-scheme.html",kicker:"Irrigated core",label:"Gezira Scheme"},{href:"sudan-railways.html",kicker:"Internal transport",label:"Sudan Railways"},{href:"port-sudan.html",kicker:"Maritime outlet",label:"Port Sudan"},{href:"egyptian-cotton-economy.html",kicker:"Nile comparison",label:"Egyptian Cotton Economy"}],
    facts:[["Principal exports","Cotton, livestock, gum arabic, hides"],["Irrigated core","Gezira Scheme"],["Administrative market","Khartoum"],["Maritime outlet","Port Sudan"],["Transport","Nile and Sudan Railways"],["Financial links","Egyptian and Italian institutions"],["Output, prices, and ownership","Open"]]
  })
});
